class LoginScreen extends StatefulWidget { const LoginScreen({super.key}); @override State<LoginScreen> createState()=>_LoginState(); }
class _LoginState extends State<LoginScreen>{
  final phone=TextEditingController(); final otp=TextEditingController(); bool sent=false;
  @override Widget build(BuildContext c)=>Scaffold(body:SafeArea(child:Padding(padding:const EdgeInsets.all(24),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[const SizedBox(height:35),Center(child:Icon(Icons.chat_bubble_rounded,size:90,color:red)),const SizedBox(height:20),const Text('Privacy WhatsApp',textAlign:TextAlign.center,style:TextStyle(fontSize:30,fontWeight:FontWeight.bold)),const Text('Private • Business • Secure',textAlign:TextAlign.center,style:TextStyle(color:Colors.white60)),const SizedBox(height:45),TextField(controller:phone,keyboardType:TextInputType.phone,decoration:const InputDecoration(labelText:'Phone number',prefixText:'+92 ',filled:true,fillColor:panel,border:OutlineInputBorder())),if(sent)...[const SizedBox(height:15),TextField(controller:otp,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'OTP',filled:true,fillColor:panel,border:OutlineInputBorder()))],const SizedBox(height:20),ElevatedButton(style:ElevatedButton.styleFrom(backgroundColor:red,foregroundColor:Colors.white,padding:const EdgeInsets.all(16)),onPressed:(){if(!sent){setState(()=>sent=true);}else{Navigator.pushReplacement(c,MaterialPageRoute(builder:(_)=>const HomeScreen()));}},child:Text(sent?'Verify OTP':'Send OTP')),const SizedBox(height:10),const Text('Real SMS OTP provider must be connected in backend before production.',textAlign:TextAlign.center,style:TextStyle(color:Colors.white38,fontSize:12))]))));
}

