class _HomeState extends State<HomeScreen>{int tab=0; final pages=const [ChatsScreen(),StatusScreen(),CallsScreen(),SettingsScreen()]; @override Widget build(BuildContext c)=>Scaffold(body:pages[tab],bottomNavigationBar:NavigationBar(backgroundColor:panel,indicatorColor:red.withOpacity(.25),selectedIndex:tab,onDestinationSelected:(i)=>setState(()=>tab=i),destinations:const [NavigationDestination(icon:Icon(Icons.chat_bubble_outline),selectedIcon:Icon(Icons.chat_bubble),label:'Chats'),NavigationDestination(icon:Icon(Icons.circle_outlined),selectedIcon:Icon(Icons.circle),label:'Status'),NavigationDestination(icon:Icon(Icons.call_outlined),selectedIcon:Icon(Icons.call),label:'Calls'),NavigationDestination(icon:Icon(Icons.settings_outlined),selectedIcon:Icon(Icons.settings),label:'Settings')]));}

